  `caption` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('pending','approved','rejected') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'approved',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`post_id`),
  UNIQUE KEY `uq_gallery_booking` (`booking_id`),
  KEY `idx_gallery_merchant` (`merchant_id`),
  KEY `idx_gallery_service` (`service_id`),
  KEY `idx_gallery_status_created` (`status`,`created_at`),
  KEY `customer_id` (`customer_id`),
  CONSTRAINT `gallery_post_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `users` (`user_id`),
  CONSTRAINT `gallery_post_ibfk_2` FOREIGN KEY (`merchant_id`) REFERENCES `merchant` (`merchant_id`),
  CONSTRAINT `gallery_post_ibfk_3` FOREIGN KEY (`service_id`) REFERENCES `service` (`service_id`),
  CONSTRAINT `gallery_post_ibfk_4` FOREIGN KEY (`booking_id`) REFERENCES `booking` (`booking_id`)
